"use client";

import { useRef, useMemo } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { TorusKnot, Environment } from "@react-three/drei";
import * as THREE from "three";

/* ── Torus scene (lives inside the Canvas) ─────────── */
function RotatingTorusKnot() {
  const meshRef = useRef<THREE.Mesh>(null!);
  const mouse = useRef({ x: 0, y: 0 });
  const { viewport } = useThree();

  // Track the mouse in NDC space
  useMemo(() => {
    if (typeof window === "undefined") return;
    const handler = (e: MouseEvent) => {
      mouse.current.x = (e.clientX / window.innerWidth) * 2 - 1;
      mouse.current.y = -(e.clientY / window.innerHeight) * 2 + 1;
    };
    window.addEventListener("mousemove", handler);
    return () => window.removeEventListener("mousemove", handler);
  }, []);

  useFrame((_, delta) => {
    if (!meshRef.current) return;
    // Slow auto-rotation
    meshRef.current.rotation.x += delta * 0.08;
    meshRef.current.rotation.y += delta * 0.12;
    // Subtle mouse influence
    meshRef.current.rotation.z +=
      (mouse.current.x * 0.02 - meshRef.current.rotation.z * 0.01) * 0.5;
  });

  return (
    <TorusKnot
      ref={meshRef}
      args={[1.6, 0.45, 256, 64]}
      position={[0, 0, 0]}
      scale={viewport.width < 6 ? 0.7 : 1}
    >
      <meshStandardMaterial
        color="#1a1a1a"
        metalness={0.92}
        roughness={0.18}
        envMapIntensity={1.4}
      />
    </TorusKnot>
  );
}

/* ── Exported wrapper with Canvas ──────────────────── */
export function HeroTorus() {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
        zIndex: 1,
        opacity: 0.55,
      }}
    >
      <Canvas
        dpr={[1, 1.5]}
        camera={{ position: [0, 0, 5.5], fov: 45 }}
        gl={{ alpha: true, antialias: true }}
        style={{ background: "transparent" }}
      >
        <ambientLight intensity={0.15} />
        <directionalLight
          position={[5, 5, 5]}
          intensity={0.6}
          color="#FF4500"
        />
        <directionalLight
          position={[-3, -2, 4]}
          intensity={0.3}
          color="#334155"
        />
        <pointLight
          position={[0, 0, 3]}
          intensity={0.4}
          color="#FF4500"
          distance={8}
        />
        <Environment preset="city" />
        <RotatingTorusKnot />
      </Canvas>
    </div>
  );
}
