"use client";

import { useEffect, useRef, useState } from "react";
import Matter from "matter-js";

const TECH = [
  "Next.js",
  "React",
  "Tailwind",
  "Flutter",
  "Supabase",
  "Solidity",
  "Framer Motion",
  "Three.js",
  "Node.js",
  "TypeScript",
];

const COLORS = [
  "#FF4500",
  "#F3F4F6",
  "#CCFF00",
  "#FF4500",
  "#3FCF8E",
  "#8B5CF6",
  "#F3F4F6",
  "#F3F4F6",
  "#68A063",
  "#3178C6",
];

export function GravityPit() {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<Matter.Engine | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const W = container.clientWidth;
    const H = container.clientHeight;
    canvas.width = W * window.devicePixelRatio;
    canvas.height = H * window.devicePixelRatio;
    canvas.style.width = `${W}px`;
    canvas.style.height = `${H}px`;

    const ctx = canvas.getContext("2d")!;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    // Engine
    const engine = Matter.Engine.create({ gravity: { x: 0, y: 1.2 } });
    engineRef.current = engine;

    // Walls (invisible)
    const wallOpts: Matter.IBodyDefinition = {
      isStatic: true,
      render: { visible: false },
      restitution: 0.4,
    };
    const floor = Matter.Bodies.rectangle(W / 2, H + 25, W + 100, 50, wallOpts);
    const leftWall = Matter.Bodies.rectangle(-25, H / 2, 50, H * 2, wallOpts);
    const rightWall = Matter.Bodies.rectangle(W + 25, H / 2, 50, H * 2, wallOpts);

    Matter.Composite.add(engine.world, [floor, leftWall, rightWall]);

    // Create pill bodies for each tech
    const pills: { body: Matter.Body; label: string; color: string; w: number; h: number }[] = [];

    TECH.forEach((name, i) => {
      const w = Math.max(name.length * 10 + 40, 90);
      const h = 38;
      const x = (W / (TECH.length + 1)) * (i + 1) + (Math.random() - 0.5) * 60;
      const y = -60 - i * 55; // Stagger drop

      const body = Matter.Bodies.rectangle(x, y, w, h, {
        chamfer: { radius: h / 2 },
        restitution: 0.45,
        friction: 0.3,
        frictionAir: 0.01,
        density: 0.002,
      });

      pills.push({ body, label: name, color: COLORS[i], w, h });
      Matter.Composite.add(engine.world, body);
    });

    // Mouse constraint for dragging
    const mouse = Matter.Mouse.create(canvas);
    mouse.pixelRatio = window.devicePixelRatio;

    const mouseConstraint = Matter.MouseConstraint.create(engine, {
      mouse,
      constraint: {
        stiffness: 0.2,
        render: { visible: false },
      },
    });
    Matter.Composite.add(engine.world, mouseConstraint);

    // Render loop
    let rafId: number;
    const render = () => {
      Matter.Engine.update(engine, 1000 / 60);
      ctx.clearRect(0, 0, W, H);

      for (const pill of pills) {
        const { body, label, color, w, h } = pill;
        const { x, y } = body.position;
        const angle = body.angle;

        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(angle);

        // Pill shape
        const r = h / 2;
        ctx.beginPath();
        ctx.moveTo(-w / 2 + r, -h / 2);
        ctx.lineTo(w / 2 - r, -h / 2);
        ctx.arc(w / 2 - r, 0, r, -Math.PI / 2, Math.PI / 2);
        ctx.lineTo(-w / 2 + r, h / 2);
        ctx.arc(-w / 2 + r, 0, r, Math.PI / 2, -Math.PI / 2);
        ctx.closePath();

        // Fill with subtle transparency
        ctx.fillStyle = "rgba(17,17,17,0.85)";
        ctx.fill();

        // Border
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        ctx.stroke();
        ctx.globalAlpha = 1;

        // Label
        ctx.fillStyle = color;
        ctx.font = "600 12px 'Space Grotesk', sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.globalAlpha = 0.9;
        ctx.fillText(label, 0, 0.5);
        ctx.globalAlpha = 1;

        ctx.restore();
      }

      rafId = requestAnimationFrame(render);
    };

    setReady(true);
    render();

    // Resize handler
    const onResize = () => {
      const nW = container.clientWidth;
      const nH = container.clientHeight;
      canvas.width = nW * window.devicePixelRatio;
      canvas.height = nH * window.devicePixelRatio;
      canvas.style.width = `${nW}px`;
      canvas.style.height = `${nH}px`;
      ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

      // Reposition walls
      Matter.Body.setPosition(floor, { x: nW / 2, y: nH + 25 });
      Matter.Body.setPosition(rightWall, { x: nW + 25, y: nH / 2 });
    };
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(rafId);
      window.removeEventListener("resize", onResize);
      Matter.Engine.clear(engine);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        minHeight: "350px",
        cursor: "grab",
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          position: "absolute",
          inset: 0,
          opacity: ready ? 1 : 0,
          transition: "opacity 0.6s ease",
        }}
      />
    </div>
  );
}
